void PM_DrawBBox(vec_t *mins,vec_t *maxs,vec_t *origin,int pcolor,float life)

{
  float in_stack_ffffff88;
  vec_t p [8] [3];
  
  p[0][1] = maxs[1] + 0.0 + origin[1];
  p[0][2] = maxs[2] + 0.0 + origin[2];
  p[0][0] = *maxs + 0.0 + *origin;
  p[1][0] = *mins + *origin;
  p[2][1] = origin[1] + mins[1];
  p[4][2] = mins[2] + origin[2];
  p[1][1] = p[0][1];
  p[1][2] = p[0][2];
  p[2][0] = p[0][0];
  p[2][2] = p[0][2];
  p[3][0] = p[1][0];
  p[3][1] = p[2][1];
  p[3][2] = p[0][2];
  p[4][0] = p[0][0];
  p[4][1] = p[0][1];
  p[5][0] = p[1][0];
  p[5][1] = p[0][1];
  p[5][2] = p[4][2];
  p[6][0] = p[0][0];
  p[6][1] = p[2][1];
  p[6][2] = p[4][2];
  p[7][0] = p[1][0];
  p[7][1] = p[2][1];
  p[7][2] = p[4][2];
  PM_ParticleLine(p[4],p[0],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[0],p[2],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[2],p[6],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[6],p[4],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[1],p[0],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[0],p[4],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[4],p[5],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[5],p[1],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[2],p[0],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[0],p[1],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[1],p[3],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[3],p[2],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[5],p[7],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[7],p[3],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[3],p[1],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[1],p[5],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[3],p[7],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[7],p[6],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[6],p[2],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[2],p[3],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[6],p[7],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[7],p[5],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[5],p[4],pcolor,life,in_stack_ffffff88);
  PM_ParticleLine(p[4],p[6],pcolor,life,in_stack_ffffff88);
  return;
}



